const stateCopy={queued:['Antre serial','Serial queue'],waiting_truck:['Menunggu armada','Awaiting fleet'],start_pending:['Menunggu tare','Awaiting tare'],ready_to_load:['Siap muat','Ready to load'],loading:['Sedang memuat','Loading'],weighed:['Timbang selesai','Weighed'],in_transit:['Menuju jetty','To jetty'],arrived:['Tiba di jetty','At jetty'],unloaded:['Diterima jetty','Jetty received'],returning:['Dalam perjalanan kembali','Returning'],returned:['Kembali terverifikasi','Return verified'],cancelled:['Dibatalkan','Cancelled'],requested:['Diminta','Requested'],planned:['Terencana','Planned'],in_progress:['Berjalan','In progress'],completed:['Selesai','Completed'],loading_complete:['Muat selesai','Loading complete'],allocated:['Dialokasi','Allocated']};
