function Action({children,icon:Icon,onClick,disabled=false,kind='',...props}){return <button type="button" className={`qc-button ${kind}`} onClick={onClick} disabled={disabled} {...props}>{Icon&&<Icon size={15}/>}<span>{children}</span></button>;}
