 const refresh=useCallback(async()=>{if(reading.current)return;reading.current=true;try{const response=await fetch('/api/v1/demo/context',{credentials:'same-origin',cache:'no-store'});const data=await response.json();if(!response.ok){if(response.status===401)onUnauthorized?.();throw new Error(apiErrorSource(data));}accept(data);}catch(failure){if(alive.current){setConnected(false);setError(failure.message);}}finally{reading.current=false;}},[accept,onUnauthorized]);
 useEffect(()=>{alive.current=true;refresh();const tick=setInterval(()=>{setClock(Date.now());if(document.visibilityState==='visible')refresh();},3000);const focus=()=>{setClock(Date.now());refresh();};window.addEventListener('focus',focus);return()=>{alive.current=false;clearInterval(tick);window.removeEventListener('focus',focus);};},[refresh]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),5500);return()=>clearTimeout(timer);},[toast]);
