 const state=snapshot?.state||{},trips=rows(state.trips),quarryTrips=trips.filter(isQuarry),products=rows(state.products),crushers=rows(state.crushers),stockpiles=rows(state.stockpiles),trucks=rows(state.trucks),jetties=rows(state.jetties),vessels=rows(state.vessels),dispatches=rows(state.dispatches),requests=rows(state.requests),config=state.quarryCilegon;
 const find=(list,id)=>list.find(item=>item.id===id),activeTrips=quarryTrips.filter(trip=>!finished(trip)),selected=quarryTrips.find(trip=>trip.id===selectedId)||activeTrips.find(trip=>trip.quarry?.allowedPurposes?.length)||activeTrips[0]||quarryTrips[0];
 const stale=!connected||!lastSync||clock-lastSync>10000,blocked=stale||busy||!!retry,admin=actor.role==='admin';
 const execute=async body=>{if(mutation.current)return null;mutation.current=true;setBusy(true);setError('');try{const response=await fetch('/api/v1/demo/actions',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw new Error(L('Respons server belum dapat dipastikan.','The server response could not be confirmed.'));}if(!response.ok){if(response.status===401)onUnauthorized?.();const code=typeof data?.error==='string'?data.error:data?.error?.code,friendly=gateReason(code,L);throw Object.assign(new Error(friendly&&friendly!==code?friendly:apiErrorSource(data)),{status:response.status});}accept(data);if(!data.state)await refresh();setRetry(null);setModal(null);setConfigDraft(null);setToast(L('Tersimpan · kedua aplikasi mengikuti data operasi yang sama.','Saved · both applications follow the same operation data.'));return data;}catch(failure){const uncertain=!failure.status||failure.status>=500;setRetry(uncertain?body:null);setError(failure.message);if(failure.status===409)await refresh();return null;}finally{mutation.current=false;setBusy(false);}};
